/** English versions of the city histories in ../cityPages.ts. */
import type { CityPage } from "../cityPages";

export const EN_CITY_PAGES: Record<string, CityPage> = {
  "romans-0": { when: "since 753 BC", text: "According to legend, Romulus founded Rome on seven hills by the river Tiber. The small town grew into the centre of an empire that ruled the whole Mediterranean, and today it is the capital of Italy.", wiki: "Rome" },
  "romans-1": { when: "from the 6th century BC", text: "Capua was one of the richest cities of Italy and lay in fertile Campania. Spartacus began his revolt in a gladiator school here in 73 BC.", wiki: "Capua (ancient city)" },
  "romans-2": { when: "from the 2nd century BC", text: "Ravenna lay among marshes by the Adriatic Sea, which made it easy to defend. In 402 it became the capital of the Western Roman Empire, and its churches still hold famous mosaics.", wiki: "Ravenna" },
  "romans-3": { when: "from the 6th century BC", text: "Greek settlers founded Naples and called it Neapolis, the New City. Wealthy Romans built summer villas here by the sea below Mount Vesuvius.", wiki: "Naples" },
  "romans-4": { when: "from the 7th century BC", text: "Ostia lay at the mouth of the Tiber and served as the port of Rome. Grain from Egypt and Africa that fed hundreds of thousands of people came into the city through it.", wiki: "Ostia Antica" },
  "romans-5": { when: "destroyed in AD 79", text: "Pompeii was buried under ash when Vesuvius erupted in AD 79. The ash preserved houses, paintings and traces of the people, so today we know how life went on in a Roman town.", wiki: "Pompeii" },
  "romans-6": { when: "from the 5th century BC", text: "The Celts founded Mediolanum and the Romans took it in 222 BC. Later the emperors lived here, and in 313 the edict that allowed Christianity was issued here. Today the city is called Milan.", wiki: "Mediolanum" },
  "romans-7": { when: "from 181 BC", text: "Aquileia began as a Roman fortress in north-eastern Italy. It grew into a rich trading city that Attila and his Huns sacked in 452.", wiki: "Aquileia" },
  "romans-8": { when: "from the 1st century BC", text: "Verona lay on important roads across the Alps. Its Roman arena still stands and today it hosts opera performances.", wiki: "Verona" },
  "romans-9": { when: "from 244 BC", text: "Brundisium was the port at the end of the Appian Way. Ships sailed from here to Greece and the east. Today the city is called Brindisi.", wiki: "Brindisi" },
  "romans-10": { when: "from the 8th century BC", text: "Spartan settlers founded Taras, the most powerful Greek port in southern Italy. The Romans took it after their war with King Pyrrhus. Today it is called Taranto.", wiki: "Taranto" },
  "romans-11": { when: "from 734 BC", text: "Greeks from Corinth founded Syracuse on Sicily, and for a long time it was one of the largest cities of the Mediterranean. Archimedes lived here and was killed by a Roman soldier when the city fell in 212 BC.", wiki: "Syracuse, Sicily" },
  "romans-12": { when: "from the 5th century BC", text: "Antium was a port of the Volsci people that Rome conquered in 338 BC. The emperors Caligula and Nero were born here. Today it is called Anzio.", wiki: "Anzio" },
  "romans-13": { when: "Etruscan city", text: "Arretium was one of the twelve Etruscan cities and became famous for its red pottery, which it sold across the empire. Today it is called Arezzo.", wiki: "Arezzo" },
  "romans-14": { when: "from 218 BC", text: "Placentia began as a Roman colony on the river Po to guard the north against the Celts. Soon after, Hannibal beat the Romans nearby. Today it is called Piacenza.", wiki: "Piacenza" },
  "romans-15": { when: "from 268 BC", text: "Ariminum lay on the Adriatic coast where the road to the north began. Close by flows the Rubicon, which Caesar crossed in 49 BC. Today it is called Rimini.", wiki: "Rimini" },
  "babylonians-0": { when: "from about 2300 BC", text: "Babylon lay on the Euphrates and became the capital of a great empire under King Hammurabi. It is famous for the Ishtar Gate and the story of the Tower of Babel.", wiki: "Babylon" },
  "babylonians-1": { when: "from about 3800 BC", text: "Ur was one of the first Sumerian cities near the mouth of the Euphrates. Archaeologists found royal tombs full of gold here and a large stepped temple, the ziggurat.", wiki: "Ur" },
  "babylonians-2": { when: "from about 4000 BC", text: "Uruk is one of the oldest cities in the world, and around 3000 BC perhaps 40,000 people lived there. One of the first scripts was invented here, and the legendary King Gilgamesh ruled here.", wiki: "Uruk" },
  "babylonians-3": { when: "from about 5000 BC", text: "Nippur was the holy city of the Sumerians. The temple of the god Enlil stood here, and kings came here to have their rule blessed.", wiki: "Nippur" },
  "babylonians-4": { when: "from about 3100 BC", text: "According to the old king lists, Kish was the first city where kings ruled after the flood. Later rulers who wanted to govern all of Mesopotamia called themselves King of Kish.", wiki: "Kish (Sumer)" },
  "babylonians-5": { when: "from about 3000 BC", text: "Lagash was a Sumerian city-state that fought its neighbour Umma over water and fields for a long time. It is known for Prince Gudea, who left behind dozens of stone statues.", wiki: "Lagash" },
  "babylonians-6": { when: "from about 5400 BC", text: "The Sumerians believed Eridu was the first city in the world, given to people by the gods. It lay near the sea in southern Mesopotamia and worshipped Enki, the god of water.", wiki: "Eridu" },
  "babylonians-7": { when: "from about 3000 BC", text: "Sippar was the city of the sun god Shamash on the Euphrates. A library with thousands of clay tablets was found in its temple.", wiki: "Sippar" },
  "babylonians-8": { when: "from about 3000 BC", text: "Larsa was a Sumerian city of the sun god. Before Babylon rose, it ruled much of southern Mesopotamia, until Hammurabi defeated it.", wiki: "Larsa" },
  "babylonians-9": { when: "from about 2000 BC", text: "Isin grew powerful after the fall of Ur, and its kings called themselves rulers of Sumer and Akkad. The goddess of healing, Gula, was worshipped here.", wiki: "Isin" },
  "babylonians-10": { when: "from about 2000 BC", text: "Borsippa lay close to Babylon and was the city of Nabu, the god of writing and wisdom. People once thought its ziggurat was the Tower of Babel.", wiki: "Borsippa" },
  "babylonians-11": { when: "from about 2300 BC", text: "Akkad was the capital of the world's first empire, founded by King Sargon. Archaeologists have never found it, and nobody knows exactly where it lies.", wiki: "Akkad (city)" },
  "babylonians-12": { when: "from about 2900 BC", text: "Mari lay on the upper Euphrates and grew rich from trade between Mesopotamia and Syria. An archive of more than 20,000 tablets and royal letters was found in its palace.", wiki: "Mari, Syria" },
  "babylonians-13": { when: "ancient", text: "Kutha was the city of Nergal, god of the underworld, not far from Babylon. According to the Bible, Assyrian kings moved people from here to Samaria.", wiki: "Kutha" },
  "babylonians-14": { when: "from about 3000 BC", text: "Umma was the rival of Lagash, and the two cities fought one of the first wars ever written down. Its king Lugalzagesi finally ruled almost all of Sumer.", wiki: "Umma" },
  "babylonians-15": { when: "from about 3000 BC", text: "Eshnunna lay in the Diyala valley and had its own law code even before Hammurabi. Archaeologists found statues of praying people with large eyes here.", wiki: "Eshnunna" },
  "germans-0": { when: "from the 13th century", text: "Berlin grew out of two merchant settlements on the river Spree. It became the capital of Prussia and later of Germany, and after the Second World War the Berlin Wall divided it for almost thirty years.", wiki: "Berlin" },
  "germans-1": { when: "from the 9th century", text: "Hamburg lies on the Elbe near the North Sea and was one of the richest cities of the Hanseatic League. Its port is still one of the largest in Europe.", wiki: "Hamburg" },
  "germans-2": { when: "from 1158", text: "Duke Henry the Lion founded Munich by a bridge over the river Isar where a toll on salt was collected. It became the capital of Bavaria, and every autumn it hosts the Oktoberfest.", wiki: "Munich" },
  "germans-3": { when: "from the 1st century BC", text: "The Romans founded Cologne as Colonia. In the Middle Ages it was the largest city in Germany, and its Gothic cathedral took over 600 years to finish, with long breaks.", wiki: "Cologne" },
  "germans-4": { when: "from the 8th century", text: "Frankfurt on the Main grew by a ford that, according to legend, the Franks crossed. Roman-German kings were elected here, and today it is the banking centre of Europe.", wiki: "Frankfurt" },
  "germans-5": { when: "from 1165", text: "Leipzig grew at a crossing of trade routes and became famous for its fairs. Johann Sebastian Bach worked here, and in 1989 demonstrations here helped bring down the communist regime.", wiki: "Leipzig" },
  "germans-6": { when: "from 1206", text: "Dresden on the Elbe was the seat of the Saxon electors, and its baroque buildings earned it the name Florence on the Elbe. Bombing destroyed it at the end of the war, and people rebuilt the centre.", wiki: "Dresden" },
  "germans-7": { when: "from 1050", text: "Nuremberg was a rich city of craftsmen and merchants where emperors often stayed. It is known for its gingerbread and, after the Second World War, the trials of Nazi war criminals.", wiki: "Nuremberg" },
  "germans-8": { when: "from the 8th century", text: "Bremen on the river Weser was the seat of an archbishop and a member of the Hanseatic League. It is still a state of its own, and children know it from the tale of the Town Musicians of Bremen.", wiki: "Bremen" },
  "germans-9": { when: "from the 1st century", text: "Aachen is known for its hot springs, already used by the Romans. Charlemagne had his favourite palace here, and German kings were crowned in Aachen Cathedral for centuries.", wiki: "Aachen" },
  "germans-10": { when: "from 179", text: "Regensburg began as a Roman fortress on the Danube. Its medieval stone bridge was a model for Charles Bridge in Prague, and the Imperial Diet met here.", wiki: "Regensburg" },
  "germans-11": { when: "from 15 BC", text: "The Romans founded Augsburg, and in the Middle Ages it was home to the Fugger banking family, the richest in Europe. The Fuggers built the Fuggerei here, the oldest social housing in the world.", wiki: "Augsburg" },
  "germans-12": { when: "from the 10th century", text: "Stuttgart grew out of a stud farm, which gave it its name. It became the capital of Württemberg, and today Mercedes and Porsche cars are made here.", wiki: "Stuttgart" },
  "germans-13": { when: "from the 12th century", text: "Hanover was the seat of the dukes of Hanover, whose family also gave Britain its kings. Today it hosts large industrial fairs every spring.", wiki: "Hanover" },
  "germans-14": { when: "from 1143", text: "Lübeck was the leading city of the Hanseatic League, an alliance of trading towns around the Baltic and North Seas. Its brick Gothic houses and the Holstentor gate are a UNESCO World Heritage Site.", wiki: "Lübeck" },
  "germans-15": { when: "from 13 BC", text: "The Romans founded Mainz where the Main flows into the Rhine. Johannes Gutenberg was born here and began printing books with movable type around 1450.", wiki: "Mainz" },
  "egyptians-0": { when: "from about 3200 BC", text: "Thebes was the capital of Egypt at the height of its power. The temples of Karnak and Luxor stand here, and across the Nile lies the Valley of the Kings with the tombs of the pharaohs.", wiki: "Thebes, Egypt" },
  "egyptians-1": { when: "from about 3100 BC", text: "According to tradition, the first pharaoh Menes founded Memphis where the Nile spreads into the delta. It was the capital of the Old Kingdom, and the pyramids of Saqqara stand nearby.", wiki: "Memphis, Egypt" },
  "egyptians-2": { when: "from 331 BC", text: "Alexander the Great founded Alexandria on the Mediterranean coast. The lighthouse, one of the Seven Wonders of the World, stood here, and so did the greatest library of the ancient world.", wiki: "Alexandria" },
  "egyptians-3": { when: "from the 26th century BC", text: "Giza lies on the west bank of the Nile opposite today's Cairo. The three great pyramids and the Great Sphinx, the most famous monuments of ancient Egypt, stand here.", wiki: "Giza" },
  "egyptians-4": { when: "from about 3000 BC", text: "Heliopolis was the city of the sun god Ra. Its priests taught how the world was created, and an obelisk more than 4,000 years old still stands here.", wiki: "Heliopolis (ancient Egypt)" },
  "egyptians-5": { when: "from about 3000 BC", text: "Sais lay in the western Nile delta and worshipped the goddess Neith. In the 7th century BC its pharaohs united Egypt once again.", wiki: "Sais, Egypt" },
  "egyptians-6": { when: "from about 3200 BC", text: "Abydos was the holy city of the god Osiris, and pilgrims came here from all over Egypt. The first pharaohs were buried here, and the temple of Seti I has a carved list of kings.", wiki: "Abydos, Egypt" },
  "egyptians-7": { when: "ancient", text: "Aswan lies at Egypt's southern border by the first cataract of the Nile. Granite for obelisks and statues came from here, and a great dam was built here in the 20th century.", wiki: "Aswan" },
  "egyptians-8": { when: "ancient", text: "Edfu is the city of Horus, the falcon-headed god. Its temple from Ptolemaic times is the best preserved temple in all of Egypt.", wiki: "Edfu" },
  "egyptians-9": { when: "ancient", text: "Kom Ombo stands on the bank of the Nile, and its temple is dedicated to two gods at once, the crocodile god Sobek and the falcon god Horus. A museum next to it holds mummified crocodiles.", wiki: "Kom Ombo" },
  "egyptians-10": { when: "from 1346 BC", text: "Pharaoh Akhenaten built Akhetaten for his one god, the sun disc Aten. After his death people left the city, and today the place is called Amarna.", wiki: "Amarna" },
  "egyptians-11": { when: "from about 3500 BC", text: "Buto was one of the oldest towns in the Nile delta and the home of the cobra goddess Wadjet. She protected Lower Egypt, and pharaohs wore her sign on their crowns.", wiki: "Buto" },
  "egyptians-12": { when: "from the 11th century BC", text: "Tanis was the capital of pharaohs in the Nile delta. Archaeologists found untouched royal tombs here with silver coffins and gold masks.", wiki: "Tanis" },
  "egyptians-13": { when: "ancient", text: "Bubastis was the city of Bastet, the cat goddess. According to Herodotus, hundreds of thousands of pilgrims sailed here for her festivals, and cats were buried here as mummies.", wiki: "Bubastis" },
  "egyptians-14": { when: "ancient", text: "Hermopolis was the city of Thoth, god of wisdom and writing, who was shown with the head of an ibis. Its priests taught that the world began here.", wiki: "Hermopolis" },
  "egyptians-15": { when: "ancient", text: "Elephantine is an island in the Nile near Aswan where ivory was traded. It has a nilometer, a staircase priests used to measure the height of the flood.", wiki: "Elephantine" },
  "americans-0": { when: "from 1790", text: "Washington was founded as the new capital of the United States on the Potomac River and is named after the first president. The White House and the Capitol stand here.", wiki: "Washington, D.C." },
  "americans-1": { when: "from 1624", text: "The Dutch founded New York as New Amsterdam, and the English renamed it in 1664. Millions of immigrants arrived through its harbour, and today it is the largest city in the United States.", wiki: "New York City" },
  "americans-2": { when: "from 1630", text: "English Puritans founded Boston. In 1773 colonists dumped tea into the harbour in protest against taxes, and soon after the War of Independence began.", wiki: "Boston" },
  "americans-3": { when: "from 1682", text: "The Quaker William Penn founded Philadelphia, and its name means brotherly love. In 1776 the delegates of the colonies signed the Declaration of Independence here.", wiki: "Philadelphia" },
  "americans-4": { when: "from 1833", text: "Chicago grew from a small settlement on Lake Michigan into a great city of railways and stockyards. After the great fire of 1871 the first skyscrapers were built here.", wiki: "Chicago" },
  "americans-5": { when: "from 1776", text: "San Francisco began as a Spanish mission on a large bay. The Gold Rush turned it into a big city, and an earthquake destroyed it in 1906.", wiki: "San Francisco" },
  "americans-6": { when: "from 1781", text: "Spanish settlers founded Los Angeles as a small village. Today it is the second largest city in the United States and home to the film studios of Hollywood.", wiki: "Los Angeles" },
  "americans-7": { when: "from 1837", text: "Atlanta began as the end station of a railway. The Union army burned it during the Civil War, and later Martin Luther King lived and preached here.", wiki: "Atlanta" },
  "americans-8": { when: "from 1851", text: "Seattle lies in the north-west of the United States between the sea and the mountains and is named after a Native American chief. Today large technology companies have their headquarters here.", wiki: "Seattle" },
  "americans-9": { when: "from 1858", text: "Gold prospectors founded Denver at the foot of the Rocky Mountains. It lies about a mile above sea level, so it is called the Mile High City.", wiki: "Denver" },
  "americans-10": { when: "from 1718", text: "The French founded New Orleans near the mouth of the Mississippi. The United States bought it with all of Louisiana in 1803, and jazz was born in the city.", wiki: "New Orleans" },
  "americans-11": { when: "from 1701", text: "The French founded Detroit as a fort on the river between the lakes. Henry Ford began making cars on the assembly line here, and the city became known as Motor City.", wiki: "Detroit" },
  "americans-12": { when: "from 1836", text: "Houston is named after Sam Houston, who won Texas its independence. It grew rich from oil and is home to NASA's mission control centre.", wiki: "Houston" },
  "americans-13": { when: "from 1729", text: "Baltimore is a port on Chesapeake Bay. The defence of its fort in 1814 inspired the song that became the American national anthem.", wiki: "Baltimore" },
  "americans-14": { when: "from 1758", text: "Pittsburgh lies where two rivers meet to form the Ohio. It grew from a fort into the steel capital of America.", wiki: "Pittsburgh" },
  "americans-15": { when: "from 1896", text: "Miami was founded when the railway reached southern Florida. Within a hundred years the small settlement became a big city full of hotels and immigrants from Cuba and Latin America.", wiki: "Miami" },
  "greeks-0": { when: "from the 2nd millennium BC", text: "Athens was the cradle of democracy and philosophy. On the Acropolis rock above the city stands the Parthenon, the temple of the goddess Athena.", wiki: "Athens" },
  "greeks-1": { when: "from the 10th century BC", text: "Sparta was a military state where boys trained as soldiers from the age of seven. Three hundred Spartans under King Leonidas fought the Persians at Thermopylae in 480 BC.", wiki: "Sparta" },
  "greeks-2": { when: "from the 8th century BC", text: "Corinth lay on the isthmus between two seas and grew rich from trade on both sides. Ships were dragged over a stone track from one sea to the other here.", wiki: "Corinth" },
  "greeks-3": { when: "from the 2nd millennium BC", text: "Thebes in Boeotia was the home of Heracles and King Oedipus in Greek myths. In 371 BC it defeated Sparta and was for a short time the strongest city in Greece.", wiki: "Thebes, Greece" },
  "greeks-4": { when: "from the 2nd millennium BC", text: "Argos is one of the oldest continuously inhabited towns in Europe. For a long time it competed with Sparta for control of the Peloponnese.", wiki: "Argos" },
  "greeks-5": { when: "from the 8th century BC", text: "Delphi lay on the slopes of Mount Parnassus, and the Greeks believed it was the centre of the world. In the temple of Apollo the priestess Pythia answered the questions of kings and ordinary people.", wiki: "Delphi" },
  "greeks-6": { when: "from 776 BC", text: "Olympia was the holy place of Zeus. The Olympic Games took place here every four years, and wars between Greek cities had to stop while they were on.", wiki: "Olympia, Greece" },
  "greeks-7": { when: "from the 10th century BC", text: "Miletus on the coast of Asia Minor founded dozens of colonies around the Mediterranean and Black Seas. The first Greek philosophers lived here, among them Thales.", wiki: "Miletus" },
  "greeks-8": { when: "from the 10th century BC", text: "Ephesus was a great port in Asia Minor. The Temple of Artemis, one of the Seven Wonders of the World, stood here, and the front of the Library of Celsus still stands.", wiki: "Ephesus" },
  "greeks-9": { when: "from 408 BC", text: "Rhodes is an island city on the route between Greece and Egypt. The giant bronze Colossus, one of the Seven Wonders of the World, stood by its harbour.", wiki: "Rhodes (city)" },
  "greeks-10": { when: "from the 2nd millennium BC", text: "Mycenae was the seat of the legendary King Agamemnon, who led the Greeks to the Trojan War. People entered the city through the Lion Gate, and the archaeologist Schliemann found a gold mask here.", wiki: "Mycenae" },
  "greeks-11": { when: "ancient", text: "Sicyon lay near Corinth and was famous for its painters and sculptors. According to one Greek tradition, painting was invented here.", wiki: "Sicyon" },
  "greeks-12": { when: "from the 8th century BC", text: "Megara lay between Athens and Corinth and founded colonies far from home. One of them, Byzantium, later became Constantinople.", wiki: "Megara" },
  "greeks-13": { when: "ancient", text: "Eretria on the island of Euboea was among the first Greek cities to found colonies in Italy. The Persians burned it in 490 BC, just before the battle of Marathon.", wiki: "Eretria" },
  "greeks-14": { when: "ancient", text: "Chalcis lies on the island of Euboea by a strait where the current changes direction several times a day. The philosopher Aristotle died here.", wiki: "Chalcis" },
  "greeks-15": { when: "from the 5th century BC", text: "Pella was the capital of Macedon. Alexander the Great was born here, and his father Philip II brought Aristotle to Macedon to teach him.", wiki: "Pella" },
  "indians-0": { when: "from the 6th century BC", text: "Delhi lies on the river Yamuna and was the capital of many empires, last of all the Mughal Empire. The Mughals built the Red Fort here, and today New Delhi is the capital of India.", wiki: "Delhi" },
  "indians-1": { when: "from the 16th century", text: "Bombay grew from seven islands that Portugal gave the English king as a dowry. The English joined the islands, and the city became India's largest port. Today it is called Mumbai and Bollywood films are made here.", wiki: "Mumbai" },
  "indians-2": { when: "from 1690", text: "The British East India Company founded Calcutta on the Hooghly River. It was the capital of British India until 1911, and today it is called Kolkata.", wiki: "Kolkata" },
  "indians-3": { when: "from 1639", text: "Madras grew around the English Fort St George on India's east coast. It was the first large English settlement in India, and today it is called Chennai.", wiki: "Chennai" },
  "indians-4": { when: "from the 2nd millennium BC", text: "Varanasi on the Ganges is one of the oldest inhabited cities in the world and the holiest city of the Hindus. Pilgrims bathe in the river, and the dead are cremated on its banks.", wiki: "Varanasi" },
  "indians-5": { when: "from the 16th century", text: "Agra was the capital of the Mughal Empire. Emperor Shah Jahan built the Taj Mahal here as a tomb for his late wife.", wiki: "Agra" },
  "indians-6": { when: "from 1727", text: "Maharaja Jai Singh II founded Jaipur to an exact plan with straight streets. The houses of the old town are painted pink, so it is called the Pink City.", wiki: "Jaipur" },
  "indians-7": { when: "from the 5th century BC", text: "Patna was once called Pataliputra and was the capital of the Maurya Empire of King Ashoka. It was one of the largest cities of the ancient world.", wiki: "Patna" },
  "indians-8": { when: "from the 18th century", text: "Lucknow was the seat of the Nawabs of Awadh and became famous for its poetry and food. In 1857 the British defended their residency here for months during the great uprising.", wiki: "Lucknow" },
  "indians-9": { when: "from 1591", text: "A sultan of Golconda founded Hyderabad, and the Charminar gate with its four towers stands in the middle of the city. Famous diamonds such as the Koh-i-Noor came from mines nearby.", wiki: "Hyderabad" },
  "indians-10": { when: "from 1537", text: "A local chieftain, Kempe Gowda, founded Bengaluru as a fort on the plateau. Today it is the centre of India's computer industry.", wiki: "Bengaluru" },
  "indians-11": { when: "from 1577", text: "Amritsar is the holy city of the Sikhs. The Golden Temple stands here in the middle of a lake, and tens of thousands of people get a free meal there every day.", wiki: "Amritsar" },
  "indians-12": { when: "from 1559", text: "A Rana of Mewar founded Udaipur by an artificial lake. Because of its lakes and palaces people call it the Venice of the East.", wiki: "Udaipur" },
  "indians-13": { when: "from the 8th century", text: "Pune was the centre of the Maratha Empire and the seat of its Peshwa ministers. Today it is a large university city.", wiki: "Pune" },
  "indians-14": { when: "from the 18th century", text: "Indore grew as a trading town in central India. In the 18th century it was ruled by the wise queen Ahilyabai Holkar.", wiki: "Indore" },
  "indians-15": { when: "from the 14th century", text: "Mysore was the capital of the Kingdom of Mysore. Every autumn it celebrates the Dasara festival, and the palace is lit by tens of thousands of light bulbs.", wiki: "Mysore" },
  "russians-0": { when: "from 1147", text: "Moscow is first mentioned in 1147 as a small fort on the Moskva River. The Russian state grew out of the Principality of Moscow, and the Kremlin and Red Square stand in the city centre.", wiki: "Moscow" },
  "russians-1": { when: "from 1703", text: "Tsar Peter the Great founded Saint Petersburg in the marshes by the Baltic Sea as a window on Europe. It was Russia's capital for two hundred years and held out through 872 days of German siege in the war.", wiki: "Saint Petersburg" },
  "russians-2": { when: "from 859", text: "Novgorod is one of the oldest Russian towns. It was a rich merchant republic where an assembly of citizens decided important matters.", wiki: "Veliky Novgorod" },
  "russians-3": { when: "from 990", text: "In the 12th century Vladimir was the capital of north-eastern Rus. Its white stone churches and the Golden Gate survived the Mongol invasion.", wiki: "Vladimir, Russia" },
  "russians-4": { when: "from 1005", text: "Kazan was the capital of a Tatar khanate on the Volga. Ivan the Terrible captured it in 1552, and today it is the centre of Tatarstan.", wiki: "Kazan" },
  "russians-5": { when: "from the 12th century", text: "Tver lay on the upper Volga and long competed with Moscow to lead the Russian principalities. The merchant Afanasy Nikitin set out from here on his journey to India.", wiki: "Tver" },
  "russians-6": { when: "from 1010", text: "Prince Yaroslav the Wise founded Yaroslavl where the Kotorosl flows into the Volga. It belongs to the Golden Ring of old towns around Moscow.", wiki: "Yaroslavl" },
  "russians-7": { when: "from 863", text: "Smolensk lies on the Dnieper on the road between Moscow and Europe. That is why it was fought over many times, among others with Napoleon in 1812.", wiki: "Smolensk" },
  "russians-8": { when: "from 903", text: "Pskov was a fortress on the western border of Rus. Its stone walls withstood many sieges, among them that of the Polish king Stephen Báthory.", wiki: "Pskov" },
  "russians-9": { when: "from 1221", text: "Nizhny Novgorod stands where the Oka flows into the Volga. In 1612 the merchant Minin and Prince Pozharsky raised an army here that drove the Poles out of Moscow.", wiki: "Nizhny Novgorod" },
  "russians-10": { when: "from 1586", text: "Samara began as a fortress on the Volga to protect the trade route. During the Second World War the government moved offices and embassies here from Moscow.", wiki: "Samara" },
  "russians-11": { when: "from 1584", text: "Arkhangelsk was for a long time Russia's only seaport. It lies by the White Sea, which is frozen part of the year.", wiki: "Arkhangelsk" },
  "russians-12": { when: "from 862", text: "Rostov the Great is one of the oldest Russian towns, on Lake Nero. It is known for its kremlin with churches and bells that ring out tunes.", wiki: "Rostov Veliky" },
  "russians-13": { when: "from 1146", text: "Tula became famous for its arms factories and samovars. Gingerbread is baked here too, and Leo Tolstoy's estate lies nearby.", wiki: "Tula, Russia" },
  "russians-14": { when: "from 1586", text: "Voronezh began as a fortress against raiders from the steppe. Peter the Great had the first ships of the Russian navy built here.", wiki: "Voronezh" },
  "russians-15": { when: "from 1723", text: "Yekaterinburg was founded in the Urals as an ironworks and fortress. In 1918 the Bolsheviks shot the last tsar, Nicholas II, and his family here.", wiki: "Yekaterinburg" },
  "zulus-0": { when: "from 1820", text: "KwaBulawayo was the royal kraal built by Shaka. The name means the place of killing, and from here Shaka directed the rise of the Zulu kingdom.", wiki: "KwaBulawayo" },
  "zulus-1": { when: "from 1826", text: "Dukuza was Shaka's last royal settlement near the coast of the Indian Ocean. In 1828 his half-brothers murdered him here. Today the town of KwaDukuza stands here.", wiki: "KwaDukuza" },
  "zulus-2": { when: "from 1873", text: "Ulundi was the royal residence of King Cetshwayo. In 1879 the British army defeated the Zulus here in the last battle of the Zulu War and burned the residence.", wiki: "Ulundi" },
  "zulus-3": { when: "from 1860", text: "Eshowe lies in the hills above the coast and is one of the oldest towns in Zululand. During the Zulu War the Zulus besieged a British garrison here for several weeks.", wiki: "Eshowe" },
  "zulus-4": { when: "from the 19th century", text: "Nongoma is the seat of today's Zulu king. It lies in the hills of northern Zululand, where many traditional Zulu families live.", wiki: "Nongoma" },
  "zulus-5": { when: "battle of 1879", text: "Isandlwana is a rocky hill below which a Zulu army defeated the British in 1879. It was one of the worst British defeats in the colonial wars.", wiki: "Battle of Isandlwana" },
  "zulus-6": { when: "19th century", text: "Mahlabatini lies on the plain by the White Umfolozi River, where the Zulu kings had their royal settlements. The area is called the valley of the kings because Shaka's ancestors are buried here.", wiki: "Mahlabatini" },
  "zulus-7": { when: "19th century", text: "Nkandla lies among thick forests and hills where the Zulus took refuge in times of war. In 1906 the rebels of chief Bambatha hid here.", wiki: "Nkandla" },
  "zulus-8": { when: "19th century", text: "Babanango is a small town on a plateau in the middle of Zululand. Zulu cattle herders knew the grasslands around it well.", wiki: "Babanango" },
  "zulus-9": { when: "19th century", text: "Ngome is a mountain forest in northern Zululand with giant trees and rare orchids. Zulu kings used it as a hunting ground and refuge.", wiki: "Ngome Forest" },
  "zulus-10": { when: "battle of 1879", text: "Hlobane is a flat-topped mountain. In 1879 the Zulus defeated British horsemen here, but lost at nearby Kambula the next day.", wiki: "Battle of Hlobane" },
  "zulus-11": { when: "from the 19th century", text: "Empangeni lies near the coast in sugar cane country. It grew from a mission station into a busy town.", wiki: "Empangeni" },
  "zulus-12": { when: "20th century", text: "Mtubatuba is named after a chief who lived here. It lies close to national parks with rhinos and elephants.", wiki: "Mtubatuba" },
  "zulus-13": { when: "19th century", text: "Pongola lies by the Pongola River on the northern border of Zululand. The river long separated Zulu land from Swaziland.", wiki: "Pongola" },
  "zulus-14": { when: "19th century", text: "The Tugela is the largest river of KwaZulu-Natal and long formed the border of the Zulu kingdom. On its upper course falls one of the highest waterfalls in the world.", wiki: "Tugela River" },
  "zulus-15": { when: "19th century", text: "The Umfolozi are two rivers, the White and the Black, between which lay the heart of the Zulu kingdom. Today there is a reserve here that saved the white rhino from extinction.", wiki: "Umfolozi" },
  "french-0": { when: "from the 3rd century BC", text: "Paris grew from a Celtic settlement on an island in the Seine. It became the capital of France, and Notre-Dame Cathedral and the Eiffel Tower stand here.", wiki: "Paris" },
  "french-1": { when: "ancient", text: "Orléans lies on the Loire. In 1429 Joan of Arc freed it from the English, which is why she is called the Maid of Orléans.", wiki: "Orléans" },
  "french-2": { when: "from 43 BC", text: "The Romans founded Lyon where the Rhône meets the Saône as the capital of Gaul. It later became famous for silk weaving, and the Lumière brothers made the first films here.", wiki: "Lyon" },
  "french-3": { when: "from 600 BC", text: "Greek sailors founded Marseille, the oldest city in France. Its port is still the largest in France, and the French national anthem is named after the city.", wiki: "Marseille" },
  "french-4": { when: "from the 3rd century BC", text: "Bordeaux lies on the Garonne near the Atlantic. It became famous for its wine, which has been shipped from here around the world for centuries.", wiki: "Bordeaux" },
  "french-5": { when: "ancient", text: "French kings were crowned in the Gothic cathedral of Reims. In 1429 Joan of Arc brought King Charles VII here to be crowned.", wiki: "Reims" },
  "french-6": { when: "ancient", text: "Rouen lies on the Seine in Normandy. In 1431 the English burned Joan of Arc here.", wiki: "Rouen" },
  "french-7": { when: "ancient", text: "Toulouse was the capital of the Visigoths and later of the counts of Toulouse. Its brick houses earned it the name Pink City, and today Airbus aircraft are built here.", wiki: "Toulouse" },
  "french-8": { when: "from 12 BC", text: "Strasbourg lies on the Rhine on the border of France and Germany and has belonged to both countries in turn. Today the European Parliament meets here.", wiki: "Strasbourg" },
  "french-9": { when: "ancient", text: "Nantes lies near the mouth of the Loire. In 1598 King Henry IV signed the Edict of Nantes here, which allowed Protestants to keep their faith.", wiki: "Nantes" },
  "french-10": { when: "ancient", text: "In the 14th century the popes lived in Avignon on the Rhône. They built a huge papal palace here, and the city has a famous bridge from a children's song.", wiki: "Avignon" },
  "french-11": { when: "ancient", text: "Dijon was the capital of the dukes of Burgundy, who ruled a rich land. It became famous for its mustard.", wiki: "Dijon" },
  "french-12": { when: "from the 11th century", text: "Lille in northern France grew rich from the cloth trade. General and President Charles de Gaulle was born here.", wiki: "Lille" },
  "french-13": { when: "from the 4th century BC", text: "The Greeks founded Nice on the Mediterranean coast. For a long time it belonged to Savoy and joined France only in 1860.", wiki: "Nice" },
  "french-14": { when: "ancient", text: "Grenoble lies in a valley surrounded by the Alps. It hosted the Winter Olympic Games in 1968.", wiki: "Grenoble" },
  "french-15": { when: "ancient", text: "Tours lies on the Loire. In 732 Charles Martel stopped an Arab army marching from Spain not far from here.", wiki: "Tours" },
  "aztecs-0": { when: "from 1325", text: "The Aztecs built Tenochtitlan on an island in Lake Texcoco, where legend says they saw an eagle on a cactus. Causeways joined it to the shore, and perhaps more than 200,000 people lived there. Mexico City stands on its ruins today.", wiki: "Tenochtitlan" },
  "aztecs-1": { when: "from 1337", text: "Tlatelolco was the sister city of Tenochtitlan on a neighbouring island. It held the largest market in the Americas, visited by tens of thousands of people every day.", wiki: "Tlatelolco (altepetl)" },
  "aztecs-2": { when: "from the 12th century", text: "Texcoco lay on the eastern shore of the lake and was part of the Triple Alliance with Tenochtitlan. Under the poet king Nezahualcoyotl it was a centre of learning and art.", wiki: "Texcoco (altepetl)" },
  "aztecs-3": { when: "from the 13th century", text: "Tlacopan on the western shore of the lake was the third and smallest member of the Aztec Triple Alliance. A causeway led to it, along which the Spaniards fled from Tenochtitlan by night.", wiki: "Tlacopan" },
  "aztecs-4": { when: "from about 100 BC", text: "Teotihuacan was a huge city with the Pyramids of the Sun and Moon, abandoned long before the Aztecs. The Aztecs believed the gods created the sun here and named it the place where gods are born.", wiki: "Teotihuacan" },
  "aztecs-5": { when: "from the 3rd century BC", text: "Cholula has the largest pyramid in the world by volume, now overgrown with grass like a hill. The Spaniards built a church on its top.", wiki: "Cholula (Mesoamerican site)" },
  "aztecs-6": { when: "from the 10th century", text: "Tula was the capital of the Toltecs, whom the Aztecs admired as masters of every craft. Giant stone warriors stand on top of a pyramid here.", wiki: "Tula (Mesoamerican site)" },
  "aztecs-7": { when: "ancient", text: "Xochimilco lies at the south of the lake, and its people grew crops on artificial floating gardens. Canals still run between the gardens, with colourful boats on them.", wiki: "Xochimilco" },
  "aztecs-8": { when: "ancient", text: "Coyoacán lay on the southern shore of the lake. After taking Tenochtitlan, Hernán Cortés lived here for a while, and centuries later the painter Frida Kahlo lived here.", wiki: "Coyoacán" },
  "aztecs-9": { when: "from the 14th century", text: "Tlaxcala was a mountain republic the Aztecs never conquered. That is why its warriors joined the Spaniards and helped them take Tenochtitlan.", wiki: "Tlaxcala (Nahua state)" },
  "aztecs-10": { when: "from the 15th century", text: "Malinalco is a temple carved straight into the rock on a mountainside. Aztec eagle and jaguar warriors were initiated here.", wiki: "Malinalco" },
  "aztecs-11": { when: "ancient", text: "Chalco lay by the lake of the same name in the south-east of the valley. The Aztecs took it after a long war in the 15th century, and its rich fields fed the capital.", wiki: "Chalco (altepetl)" },
  "aztecs-12": { when: "from the 12th century", text: "Azcapotzalco was the capital of the Tepanecs, to whom the Aztecs long paid tribute. In 1428 the Aztecs and Texcoco defeated it, and the rise of the Aztec Empire began.", wiki: "Azcapotzalco" },
  "aztecs-13": { when: "ancient", text: "Cuauhnahuac lay in a warm valley south of the mountains, and the Aztecs got cotton from it. Cortés built a palace here, and today the city is called Cuernavaca.", wiki: "Cuernavaca" },
  "aztecs-14": { when: "ancient", text: "Huexotzinco lay on the slopes of the volcano Iztaccíhuatl and, like Tlaxcala, resisted the Aztecs. It fought the so-called flower wars with them, in which captives were taken for sacrifice.", wiki: "Huejotzingo" },
  "aztecs-15": { when: "ancient", text: "Tepeyacac was a hill on the northern shore of the lake, reached by a causeway from Tenochtitlan. According to tradition, the Virgin of Guadalupe appeared here in 1531, and a pilgrimage basilica stands here today.", wiki: "Tepeyac" },
  "chinese-0": { when: "from 1045 BC", text: "Beijing was the capital of most of China's last dynasties. In its centre lies the Forbidden City, the emperors' palace with almost 1,000 buildings.", wiki: "Beijing" },
  "chinese-1": { when: "from the 11th century BC", text: "Xi'an was once called Chang'an and was the capital of more than ten dynasties. The Silk Road began here, and the Terracotta Army of the first emperor lies nearby.", wiki: "Xi'an" },
  "chinese-2": { when: "from the 10th century", text: "Shanghai was a fishing and trading town at the mouth of the Yangtze. In the 19th century it opened to foreigners, and today it is the largest city in China.", wiki: "Shanghai" },
  "chinese-3": { when: "from the 5th century BC", text: "Nanjing lies on the Yangtze, and its name means southern capital. It was the capital of China several times, and its city walls are among the longest in the world.", wiki: "Nanjing" },
  "chinese-4": { when: "from 214 BC", text: "Canton lies on the Pearl River in southern China and has traded with foreigners by sea since ancient times. For a long time it was the only Chinese port European merchants were allowed into. Today it is called Guangzhou.", wiki: "Guangzhou" },
  "chinese-5": { when: "from the 2nd millennium BC", text: "Luoyang lies near the Yellow River and was the capital of many ancient dynasties. Monks carved tens of thousands of Buddha statues into the cliffs above the river here.", wiki: "Luoyang" },
  "chinese-6": { when: "from the 2nd century BC", text: "Hangzhou lies by the West Lake, which poets have praised. In the 12th and 13th centuries it was China's capital, and Marco Polo called it the finest city in the world.", wiki: "Hangzhou" },
  "chinese-7": { when: "from the 4th century BC", text: "Chengdu lies in the fertile Sichuan basin. Nearby is an irrigation system over 2,000 years old that still works, and pandas live in the area.", wiki: "Chengdu" },
  "chinese-8": { when: "from the 4th century BC", text: "Kaifeng on the Yellow River was the capital under the Song dynasty and one of the largest cities in the world. The river flooded it many times.", wiki: "Kaifeng" },
  "chinese-9": { when: "ancient", text: "Wuhan was formed from three towns where the Han River flows into the Yangtze. In 1911 an uprising broke out here that overthrew the last Chinese emperor.", wiki: "Wuhan" },
  "chinese-10": { when: "from 514 BC", text: "Suzhou is criss-crossed by canals and is called the Venice of China. It is famous for its classical gardens and silk making.", wiki: "Suzhou" },
  "chinese-11": { when: "from 1404", text: "Tianjin began as a fortress and port for Beijing where the Grand Canal reaches the sea. Today it is one of the largest cities in China.", wiki: "Tianjin" },
  "chinese-12": { when: "from the 4th century BC", text: "Chongqing lies in the mountains where the Jialing meets the Yangtze. During the Second World War the Chinese government was based here, and the Japanese bombed it many times.", wiki: "Chongqing" },
  "chinese-13": { when: "from 214 BC", text: "Guilin is surrounded by steep limestone hills and the Li River. Chinese painters have painted the landscape around it for centuries.", wiki: "Guilin" },
  "chinese-14": { when: "from the 3rd century BC", text: "Datong lies in the north near the Great Wall and was the capital of the Northern Wei dynasty. Nearby are the Yungang caves with thousands of carved Buddha statues.", wiki: "Datong" },
  "chinese-15": { when: "ancient", text: "Jinan is called the City of Springs because dozens of springs rise in it. It lies near the holy mountain Tai Shan.", wiki: "Jinan" },
  "english-0": { when: "from AD 47", text: "The Romans founded London as Londinium by a crossing of the Thames. It became the capital of England and later the centre of the largest empire in history.", wiki: "London" },
  "english-1": { when: "from AD 71", text: "The Romans founded York as the fortress of Eboracum, and later the Vikings ruled it as Jorvik. Its Gothic minster is one of the largest in northern Europe.", wiki: "York" },
  "english-2": { when: "from the 6th century", text: "Nottingham has a castle on a rock with hundreds of caves beneath it. In the legend, the sheriff who fought Robin Hood of Sherwood Forest lived here.", wiki: "Nottingham" },
  "english-3": { when: "from the 1st century", text: "In 597 Saint Augustine began spreading Christianity among the English in Canterbury. In 1170 Archbishop Thomas Becket was murdered in the cathedral, and the city became a place of pilgrimage.", wiki: "Canterbury" },
  "english-4": { when: "from the 9th century", text: "Oxford grew up by a ford where cattle crossed the Thames. Teaching began here at the end of the 11th century, and the oldest university in the English-speaking world grew from it.", wiki: "Oxford" },
  "english-5": { when: "from the 1st century", text: "Cambridge lies on the river Cam. In 1209 scholars fled here from Oxford and founded a university where Newton and Darwin later studied.", wiki: "Cambridge" },
  "english-6": { when: "from the 11th century", text: "Bristol was a great port in the west of England. John Cabot sailed from here in 1497 and reached North America.", wiki: "Bristol" },
  "english-7": { when: "from 1207", text: "Liverpool was the port from which ships sailed to America. The Beatles started playing here in the 1960s.", wiki: "Liverpool" },
  "english-8": { when: "from AD 79", text: "Manchester grew from a Roman fort, and in the 18th century it became the world's first industrial city. Steam engines drove its cotton mills.", wiki: "Manchester" },
  "english-9": { when: "from the 7th century", text: "Birmingham was a small market village that grew into the city of a thousand trades in the Industrial Revolution. The inventors James Watt and Matthew Boulton worked here.", wiki: "Birmingham" },
  "english-10": { when: "ancient", text: "Winchester was the capital of the Anglo-Saxon kingdom of Wessex under King Alfred the Great. The writer Jane Austen is buried in its cathedral.", wiki: "Winchester" },
  "english-11": { when: "ancient", text: "Dover lies at the narrowest point of the English Channel, where France can be seen on a clear day. White chalk cliffs and a castle tower above the harbour.", wiki: "Dover" },
  "english-12": { when: "from the 13th century", text: "Plymouth is a port in south-west England. Francis Drake sailed from here against the Spanish Armada, and in 1620 the Mayflower carried the Pilgrims from here to America.", wiki: "Plymouth" },
  "english-13": { when: "from the 5th century", text: "Leeds grew from the wool trade and became a great cloth-making city in the Industrial Revolution. Today it is a big commercial and university city.", wiki: "Leeds" },
  "english-14": { when: "from the 7th century", text: "In the Middle Ages Norwich was one of the largest and richest cities of England after London. It grew rich from wool and has a cathedral with a tall spire.", wiki: "Norwich" },
  "english-15": { when: "from AD 60", text: "The Romans built Bath by its hot springs and called it Aquae Sulis. The Roman baths survive to this day, and in the 18th century high society came here from all over England.", wiki: "Bath, Somerset" },
  "mongols-0": { when: "from 1220", text: "Karakorum was the capital of the Mongol Empire under Genghis Khan's successors. Envoys from Europe and Asia came here to the court of the Great Khan. The Erdene Zuu monastery stands on the site today.", wiki: "Karakorum" },
  "mongols-1": { when: "13th century", text: "According to archaeologists, Avraga was Genghis Khan's first base by the Kherlen River. The remains of his camp and workshops have been found on the site.", wiki: "Avraga" },
  "mongols-2": { when: "from 1267", text: "Kublai Khan had Khanbaliq built as the capital of the Yuan dynasty in China. Marco Polo described its splendour, and Beijing stands on the site today.", wiki: "Khanbaliq" },
  "mongols-3": { when: "from 1256", text: "Shangdu was the summer capital of Kublai Khan. Europeans know it from a poem as Xanadu, a place of fabulous luxury.", wiki: "Shangdu" },
  "mongols-4": { when: "from the 13th century", text: "Sarai on the lower Volga was the capital of the Golden Horde, which ruled over Rus. It was one of the largest medieval cities and traded with both Europe and China.", wiki: "Sarai (city)" },
  "mongols-5": { when: "ancient", text: "Tabriz was the capital of the Mongol Ilkhans in Persia. Its great covered bazaar is one of the oldest in the world.", wiki: "Tabriz" },
  "mongols-6": { when: "from 1302", text: "The Ilkhans built Soltaniyeh as their new capital. What remains is the huge tomb of Khan Öljaitü with one of the largest domes in the world.", wiki: "Soltaniyeh" },
  "mongols-7": { when: "13th century", text: "Almaliq was the capital of the Chagatai Khanate in Central Asia on the Silk Road. Only ruins remain of it today.", wiki: "Almaliq" },
  "mongols-8": { when: "from 1639", text: "Ulaanbaatar began as a travelling monastery that moved from place to place. Today it is the capital of Mongolia, and almost half the country's people live there.", wiki: "Ulaanbaatar" },
  "mongols-9": { when: "from 1974", text: "Erdenet was founded by a large copper mine. It is the second largest city in Mongolia.", wiki: "Erdenet" },
  "mongols-10": { when: "from 1961", text: "Darkhan was built as an industrial city in northern Mongolia. Its name means blacksmith.", wiki: "Darkhan" },
  "mongols-11": { when: "from 1762", text: "Khovd began as a fortress of the Qing dynasty in western Mongolia. It lies in a region where many different peoples live.", wiki: "Khovd" },
  "mongols-12": { when: "20th century", text: "Mörön lies in northern Mongolia near Lake Khövsgöl. Old standing stones carved with deer stand in the area.", wiki: "Mörön" },
  "mongols-13": { when: "20th century", text: "Choibalsan lies in eastern Mongolia on the Kherlen River. It is named after Khorloogiin Choibalsan, who ruled the country in the 1930s and 1940s.", wiki: "Choibalsan (city)" },
  "mongols-14": { when: "20th century", text: "Bayankhongor lies between the Khangai mountains and the Gobi Desert. Herds of sheep and camels graze around it.", wiki: "Bayankhongor" },
  "mongols-15": { when: "from 1733", text: "Uliastai began as a Qing fortress from which Chinese officials governed Mongolia. It lies in the mountains in the west of the country.", wiki: "Uliastai" },
  "czechs-0": { when: "from the 9th century", text: "Prague grew below Prague Castle on the Vltava, and under Charles IV it was one of the largest cities in Europe. Charles founded the university and the New Town here and built the stone bridge we now call Charles Bridge.", wiki: "Prague" },
  "czechs-1": { when: "from the 11th century", text: "Brno grew below Špilberk Castle and is the largest city in Moravia. In 1645 it held out against a Swedish siege, and in a monastery here Gregor Mendel discovered the laws of heredity.", wiki: "Brno" },
  "czechs-2": { when: "from the 13th century", text: "Kutná Hora grew rich from the silver mined here in the Middle Ages. Prague groschen were minted here, and the Church of St Barbara was built with the miners' money.", wiki: "Kutná Hora" },
  "czechs-3": { when: "from 1295", text: "King Wenceslas II founded Plzeň as a royal town where rivers meet. In 1842 the first pale lager was brewed here, and beer called pilsner is named after the city all over the world.", wiki: "Plzeň" },
  "czechs-4": { when: "from the 11th century", text: "Olomouc was for a long time the capital of Moravia and the seat of bishops. The Holy Trinity Column, a UNESCO World Heritage Site, and an astronomical clock stand on its square.", wiki: "Olomouc" },
  "czechs-5": { when: "from the 13th century", text: "Hradec Králové was a dowry town of the Czech queens, which gave it its name. In 1866 the Prussians defeated the Austrian army near it.", wiki: "Hradec Králové" },
  "czechs-6": { when: "from 1265", text: "King Ottokar II founded České Budějovice as a strong royal town with a large square market place. It is famous for its beer, and the first horse-drawn railway on the continent ran from here to Linz.", wiki: "České Budějovice" },
  "czechs-7": { when: "from the 13th century", text: "Kolín lies on the Elbe, and in 1757 the Austrian army defeated the Prussian king Frederick the Great nearby. The Military Order of Maria Theresa was founded to honour the victory.", wiki: "Kolín" },
  "czechs-8": { when: "from 1420", text: "The Hussites founded Tábor on a hill above the river Lužnice and named it after a mountain in the Bible. They dug passages beneath the town to store supplies and hide people.", wiki: "Tábor" },
  "czechs-9": { when: "from the 12th century", text: "Cheb was an imperial town with a palace of Frederick Barbarossa. In 1634 the general Albrecht von Wallenstein was murdered here.", wiki: "Cheb" },
  "czechs-10": { when: "from 1057", text: "Litoměřice lies where the Ohře flows into the Elbe, in fertile country called the Garden of Bohemia. A chapter of canons was founded here in the 11th century, and a bishop has lived here since the 17th century.", wiki: "Litoměřice" },
  "czechs-11": { when: "from the 11th century", text: "Znojmo stands on a rock above the river Dyje. The rotunda at its castle has paintings of the Přemyslid princes, and wine and gherkins are grown around it.", wiki: "Znojmo" },
  "czechs-12": { when: "from the 13th century", text: "Jihlava grew on silver, and its mining law was adopted across half of Europe. Kilometres of cellars and passages run beneath its square, and the composer Gustav Mahler spent his childhood here.", wiki: "Jihlava" },
  "czechs-13": { when: "from the 13th century", text: "Opava was the capital of the Czech part of Silesia. In 1820 the rulers of Europe met here for a congress.", wiki: "Opava" },
  "czechs-14": { when: "from the 13th century", text: "Písek grew by a ford over the Otava, where gold was panned from the sand. The oldest surviving stone bridge in Bohemia stands here.", wiki: "Písek" },
  "czechs-15": { when: "from the 12th century", text: "Žatec is surrounded by hop gardens, and its hops have been sent to breweries all over the world. The landscape of hops is a UNESCO World Heritage Site.", wiki: "Žatec" },
};
